-- ----------------------------
-- Table structure for yshop_crm_customer
-- ----------------------------
DROP TABLE IF EXISTS `yshop_crm_customer`;
CREATE TABLE `yshop_crm_customer`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'ID',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '客户名称',
  `mobile` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '手机',
  `telephone` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '电话',
  `deal_status` int NOT NULL DEFAULT 0 COMMENT '成交状态0未成交1成交',
  `deal_time` datetime NULL DEFAULT NULL COMMENT '成交时间',
  `is_lock` tinyint(1) NULL DEFAULT 0 COMMENT '1锁定',
  `level` int NOT NULL DEFAULT 0 COMMENT '客户级别ID',
  `industry` int NOT NULL DEFAULT 0 COMMENT '客户行业ID',
  `tags` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT ' 客户标签',
  `source` int NOT NULL DEFAULT 0 COMMENT '客户来源ID',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `user_id` int NULL DEFAULT 0 COMMENT '前台用户ID',
  `owner_user_id` bigint NULL DEFAULT NULL COMMENT '负责人ID',
  `province` int NULL DEFAULT 0 COMMENT '省份id',
  `city` int NULL DEFAULT 0 COMMENT '城市ID',
  `area` int NULL DEFAULT 0 COMMENT '区域ID',
  `address_str` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '地址组合字符串',
  `detail_address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '详细地址',
  `lng` double(14, 11) NULL DEFAULT NULL COMMENT '地理位置经度',
  `lat` double(14, 11) NULL DEFAULT NULL COMMENT '地理位置维度',
  `next_time` datetime NULL DEFAULT NULL COMMENT '下次联系时间',
  `follow_time` datetime NULL DEFAULT NULL COMMENT '最后跟进时间',
  `collect_time` datetime NULL DEFAULT NULL COMMENT '领取时间',
  `weixin` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '微信',
  `qq` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'QQ',
  `purchase_total` decimal(18, 2) NULL DEFAULT 0.00 COMMENT '消费总额',
  `purchase_times` int NULL DEFAULT 0 COMMENT '消费次数',
  `follow_status` tinyint(1) NULL DEFAULT 1 COMMENT '跟进状态1|新客\n2|待再次沟通\n3|有意向\n4|已加微信\n5|转商机\n0|无效',
  `rw_user_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '读写权限用户',
  `ro_user_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '只读权限用户',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '创建者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除',
  `tenant_id` bigint NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 137 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '客户表' ROW_FORMAT = DYNAMIC;

